#!/usr/bin/env node
'use strict';
/**
 * scripts/check-codex-plugin-drift.cjs
 *
 * CI gate that asserts the committed `.codex-plugin/plugin.json` and
 * `.cursor-plugin/plugin.json` snapshots match the deterministic output of
 * scripts/build-distribution-bundles.cjs (Codex + Cursor converters).
 *
 * Background: per Phase 28.8 / Q7 decision, the Codex + Cursor manifests are
 * GENERATED by the Tier-2 converters from canonical sources (package.json,
 * .claude-plugin/plugin.json, README.md). The committed mirrors at
 * `.codex-plugin/plugin.json` and `.cursor-plugin/plugin.json` exist so that
 * a `git clone` consumer sees the same artifact a fresh build would emit.
 * Without a drift gate, the two surfaces silently desynchronize (mismatched
 * keywords / longDescription / defaultPrompt etc.). This gate is that pin.
 *
 * Behavior:
 *   - Runs the generator into a tmpdir (does NOT mutate the committed dist/).
 *   - Reads the generator output AND the committed snapshot for each channel.
 *   - Byte-compares them. Any difference fails the gate.
 *   - --rebaseline writes the generator output back to the committed snapshot
 *     so a human can review + commit the resulting diff.
 *
 * Mirrors the baseline-ratchet pattern of scripts/check-feature-counts.cjs:
 *   - Default: read-only assertion, exit 0/1.
 *   - --check: same as default but quieter on success (CI-friendly).
 *   - --rebaseline: write the new baseline. Use after intentional changes
 *     to package.json#description, README, claude-plugin/plugin.json, etc.
 *
 * Run via:  npm run validate:codex-plugin
 *           node scripts/check-codex-plugin-drift.cjs --rebaseline
 * Exit code 0 = clean, 1 = drift detected.
 */

const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const REPO_ROOT = path.resolve(__dirname, '..');

// Channels validated by this gate. Both consume the same Tier-2 build pipeline
// (build-distribution-bundles.cjs) but ship their manifests at distinct paths.
const CHANNELS = Object.freeze([
  {
    channelId: 'codex-plugin',
    manifestRel: '.codex-plugin/plugin.json',
  },
  {
    channelId: 'cursor-marketplace',
    manifestRel: '.cursor-plugin/plugin.json',
  },
]);

function readFileOrNull(p) {
  try { return fs.readFileSync(p, 'utf8'); }
  catch { return null; }
}

function rmRf(p) {
  fs.rmSync(p, { recursive: true, force: true });
}

/**
 * Generate fresh manifests via build-distribution-bundles.cjs into a tmpdir.
 * Returns { tmpRoot, generated: Map<channelId, string|null> }.
 *
 * The caller is responsible for rmRf'ing tmpRoot when done.
 */
function generateFresh() {
  const bundler = require('./build-distribution-bundles.cjs');
  const runtimesModule = require('./lib/install/runtimes.cjs');
  const packageJson = require(path.join(REPO_ROOT, 'package.json'));

  const tmpRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'codex-plugin-drift-'));
  const generated = new Map();

  try {
    for (const ch of CHANNELS) {
      bundler.buildAllChannels({
        sourceRoot: REPO_ROOT,
        outRoot: tmpRoot,
        runtimesModule,
        packageJson,
        channelFilter: ch.channelId,
      });
      const out = readFileOrNull(path.join(tmpRoot, ch.channelId, ch.manifestRel));
      generated.set(ch.channelId, out);
    }
  } catch (e) {
    rmRf(tmpRoot);
    throw e;
  }

  return { tmpRoot, generated };
}

function main(argv) {
  const isCheck = argv.includes('--check');
  const isRebaseline = argv.includes('--rebaseline');

  let result;
  try {
    result = generateFresh();
  } catch (e) {
    console.error('check-codex-plugin-drift: generator FAILED to run');
    console.error('  ' + e.message);
    return 2;
  }

  const { tmpRoot, generated } = result;
  const drifts = [];

  try {
    for (const ch of CHANNELS) {
      const committedPath = path.join(REPO_ROOT, ch.manifestRel);
      const committed = readFileOrNull(committedPath);
      const fresh = generated.get(ch.channelId);

      if (fresh === null) {
        drifts.push({
          channel: ch.channelId,
          manifestRel: ch.manifestRel,
          reason: 'generator produced no manifest at expected path',
        });
        continue;
      }

      if (isRebaseline) {
        fs.mkdirSync(path.dirname(committedPath), { recursive: true });
        fs.writeFileSync(committedPath, fresh, 'utf8');
        if (!isCheck) {
          console.log(`check-codex-plugin-drift: rebaselined ${ch.manifestRel}`);
        }
        continue;
      }

      if (committed === null) {
        drifts.push({
          channel: ch.channelId,
          manifestRel: ch.manifestRel,
          reason: 'committed snapshot missing — run with --rebaseline',
        });
        continue;
      }

      if (committed !== fresh) {
        drifts.push({
          channel: ch.channelId,
          manifestRel: ch.manifestRel,
          reason: 'committed snapshot disagrees with generator output',
          committed,
          fresh,
        });
      }
    }
  } finally {
    rmRf(tmpRoot);
  }

  if (isRebaseline) {
    if (!isCheck) {
      console.log('check-codex-plugin-drift: rebaseline complete — review the diff and commit.');
    }
    return 0;
  }

  if (drifts.length === 0) {
    if (!isCheck) {
      console.log('check-codex-plugin-drift: OK');
      for (const ch of CHANNELS) {
        console.log(`  ${ch.manifestRel}: matches generator`);
      }
    }
    return 0;
  }

  console.error('check-codex-plugin-drift: DRIFT DETECTED');
  console.error('');
  for (const d of drifts) {
    console.error(`  ${d.manifestRel} (${d.channel})`);
    console.error(`    ${d.reason}`);
    if (d.committed !== undefined && d.fresh !== undefined) {
      // Print a small unified-style line-diff hint to make the failure
      // self-diagnosable in CI logs without forcing the user to run the
      // build locally.
      const committedLines = d.committed.split('\n');
      const freshLines = d.fresh.split('\n');
      const maxLines = Math.max(committedLines.length, freshLines.length);
      let shown = 0;
      for (let i = 0; i < maxLines && shown < 10; i++) {
        if (committedLines[i] !== freshLines[i]) {
          if (committedLines[i] !== undefined) console.error(`    - ${committedLines[i]}`);
          if (freshLines[i] !== undefined)     console.error(`    + ${freshLines[i]}`);
          shown++;
        }
      }
      if (shown === 10) {
        console.error('    … (further differences truncated)');
      }
    }
    console.error('');
  }
  console.error('Fix: run `npm run validate:codex-plugin -- --rebaseline` to regen the');
  console.error('committed snapshots from generator output, then review + commit the diff.');
  return 1;
}

module.exports = { main, generateFresh, CHANNELS };

if (require.main === module) {
  process.exitCode = main(process.argv.slice(2));
}
